"""BOM delta RS-CAP-12L (lit) vs RS-CAP-12 (plain), per sconce. Run: python3 bom_delta.py -> BOM-delta.md + BOM-delta.csv"""
DK = "https://www.digikey.com/en/products/detail/"
rows = [  # item, qty/unit, source, (q1, q100, q500) per-unit cost, status, note
 ("LED LUXEON 2835 2700K CRI90 L128-2790SA35A0DF1", 6, DK + "lumileds/L128-2790SA35A0DF1/27376536", (6 * 0.19, 6 * 0.06982, 6 * 0.05885), "V", "100 units = 600 pcs -> 500 break $0.06982; 500 units -> 2,000 break $0.05885"),
 ("Resistor 100R 0603 1% (RC0603FR-07100RL)", 2, DK + "yageo/RC0603FR-07100RL/726888", (2 * 0.10, 2 * 0.0136, 2 * 0.0075), "V", "Digi-Key stock 0 on 11/10; JLC basic part equivalent"),
 ("CCR onsemi NSI45020AT1G 20 mA SOD-123", 1, DK + "onsemi/NSI45020AT1G/2096220", (0.21, 0.1096, 0.09518), "V", ""),
 ("Diode 1N4148WS SOD-323 (reverse polarity)", 1, "-", (0.05, 0.02, 0.01), "E", "not loaded"),
 ("TVS 0402: cap 12 V UNIDIRECTIONAL, hub 15 V standoff", 2, "-", (0.20, 0.06, 0.04), "E", "rev B: the 12 V bidirectional part was wrong on both boards (see PCB-SPEC.md)"),
 ("PTC 100 mA hold 0603 (F1, hub board)", 1, "-", (0.10, 0.04, 0.03), "E", "rev B: protects the 26 AWG tap off the 2 A rail"),
 ("Spring pin Mill-Max 0919-0-15-20-89-14-11-0 (rev B: RETURN contact)", 1, DK + "mill-max-manufacturing-corp/0919-0-15-20-89-14-11-0/6193088", (1.52, 1.0954, 0.97772), "V", ""),
 ("RS-HUB-12L-PLUNGER turned brass, hard gold (rev B centre contact)", 1, "RFQ", (5.0, 0.45, 0.30), "E", "replaces the centre spring pin: no catalogue pin has more than 3 mm of stroke, the stack needs 4.2"),
 ("Compression spring OD 2.3 x wire 0.20 x 11.2 free, stainless", 1, "-", (0.60, 0.20, 0.12), "E", "catalogue part not yet picked (Lee Spring / Century class)"),
 ("RS-CAP-12L-SLEEVE turned PEEK, counterbored (rev B; was cut tubing)", 1, "RFQ", (4.0, 0.80, 0.50), "E", "the counterbore for the pin head makes it a turned part"),
 ("PTFE wire 30 AWG, 40 mm + 26 AWG pair 60 mm (hub)", 1, "-", (0.05, 0.04, 0.03), "E", ""),
 ("Loctite 270 + activator 7649, UV adhesive", 1, "-", (0.10, 0.05, 0.04), "E", ""),
 ("RS-CAP-12L-DOME turned brass, chrome", 1, "RFQ", (45.0, 7.50, 5.00), "E", "plain RS-CAP-12 turned brass is estimated $4-8 @100 (BOM.md line 4 note); this one is hollow with an LH-threaded boss"),
 ("RS-CAP-12L-CORE turned brass, EN, stepped bore, 1 cross-hole", 1, "RFQ", (35.0, 5.50, 3.50), "E", ""),
 ("RS-CAP-12L-PIN headed, turned, hard gold", 1, "RFQ", (5.0, 0.40, 0.25), "E", ""),
 ("RS-CAP-12L-LOUVER micro-SLA (moulded at 500)", 1, "RFQ", (25.0, 8.00, 1.20), "E", "moulding tool est $6-9k one-off, not in the unit cost"),
 ("RS-CAP-12L-WINDOW PC ring, satin", 1, "RFQ", (8.0, 1.00, 0.40), "E", ""),
 ("RS-HUB-12L-CARRIER PEEK machined (body + guard tube)", 1, "RFQ", (15.0, 2.50, 1.20), "E", ""),
 ("RS-PCB-12L-LED fab + bottom SMT", 1, "JLCPCB", (8.0, 1.00, 0.55), "E", "board + assembly share; setup fees spread over the run"),
 ("RS-PCB-12L-HUB fab + top SMT", 1, "JLCPCB", (6.0, 0.80, 0.45), "E", ""),
 ("Assembly + test labour (15 min @ $20/h; 10 min at 500)", 1, "-", (5.0, 5.0, 3.33), "E", ""),
]
minus = [
 ("Plain cap RS-CAP-12 (BOM.md 12in line 4, chrome)", 1, "build/BOM.md", (5.15, 3.40, 2.65), "E", "removed"),
 ("Cap felt washer (BOM.md line 5; the lit cap has no felt)", 1, "build/BOM.md", (0.16, 0.16, 0.14), "E", "removed"),
]
add = [sum(r[3][i] for r in rows) for i in range(3)]
sub = [sum(r[3][i] for r in minus) for i in range(3)]
d = [a - s for a, s in zip(add, sub)]
L = ["# BOM delta: lit cap RS-CAP-12L vs plain cap RS-CAP-12 (per 12 in sconce)", "",
     "Generated by `bom_delta.py`. Rev B, 2026-11-11. V = price read off the live page on 2026-11-10 (see link-check.txt), E = estimate, not a quote. Nothing ordered.",
     "Columns are cost per sconce when building 1 / 100 / 500 sconces.", "",
     "| Item | Qty | Source | 1 | 100 | 500 | Status | Note |", "|---|---|---|---|---|---|---|---|"]
for r in rows:
    L.append(f"| {r[0]} | {r[1]} | {r[2]} | ${r[3][0]:.2f} | ${r[3][1]:.2f} | ${r[3][2]:.2f} | {r[4]} | {r[5]} |")
L.append(f"| **Added** | | | **${add[0]:.2f}** | **${add[1]:.2f}** | **${add[2]:.2f}** | | |")
for r in minus:
    L.append(f"| minus {r[0]} | {r[1]} | {r[2]} | -${r[3][0]:.2f} | -${r[3][1]:.2f} | -${r[3][2]:.2f} | {r[4]} | {r[5]} |")
L.append(f"| **Delta per sconce** | | | **+${d[0]:.2f}** | **+${d[1]:.2f}** | **+${d[2]:.2f}** | | |")
vsum = [sum(r[3][i] for r in rows if r[4] == "V") for i in range(3)]
L += ["", f"Verified share of the added cost at 100: ${vsum[1]:.2f} of ${add[1]:.2f}. The rest is the turned/printed/moulded custom parts, "
      "which only the RFQ (rfq/dome-cap-lit/) can turn into numbers. The louver is the swing item: $8 micro-SLA at 100, ~$1.20 moulded at 500 plus tooling.",
      "", "Unchanged: adapter (24 W, the label light adds 0.24 W), inline dimmer, insert. The lit sconce needs RS-HUB-01 rev B and the rev B backplate, which the plain sconce uses too, so they add nothing here. The PET label washer and centre backing ring are on every sconce (build/BOM.md 6a, 6b)."]
open("BOM-delta.md", "w").write("\n".join(L) + "\n")
with open("BOM-delta.csv", "w") as f:
    f.write("item,qty,source,cost_1,cost_100,cost_500,status,note\n")
    for r in rows + [("MINUS " + m[0],) + m[1:] for m in minus]:
        f.write(f"\"{r[0]}\",{r[1]},{r[2]},{r[3][0]:.4f},{r[3][1]:.4f},{r[3][2]:.4f},{r[4]},\"{r[5]}\"\n")
print("added", [round(x, 2) for x in add], "delta", [round(x, 2) for x in d], "verified@100", round(vsum[1], 2))
